"""Frozen oracle for reppy robots.txt semantics, compiled from the unmodified pinned C++ sources.

Run outside the ECDEV tree:
  python reppy_gpp_oracle.py <reppy checkout at e92f22e0 with submodules> <existing reppy-robots.json> <out.json>
Compiles rep-cpp (9c1278b7) and url-cpp (f9f53c7c) with g++ -std=c++14 together with the harness
embedded below, then (1) re-executes every case of the existing MSVC-built fixture and records
whether the g++ build agrees, and (2) records Rep::Robots::robotsUrl for a URL corpus.
"""
import hashlib, json, pathlib, subprocess, sys, tempfile

HARNESS = r'''
#include <iostream>
#include <iomanip>
#include <string>
#include "robots.h"
static std::string unhex(const std::string& hex) {
    std::string out;
    for (size_t i = 0; i < hex.size(); i += 2) out.push_back(static_cast<char>(std::stoul(hex.substr(i, 2), nullptr, 16)));
    return out;
}
int main() {
    std::string op;
    while (std::cin >> op) {
        if (op == "allowed") {
            std::string content, url, agent;
            std::cin >> content >> url >> agent;
            Rep::Robots robots(unhex(content), "https://shop.example/robots.txt");
            auto selected = unhex(agent);
            std::cout << robots.allowed(unhex(url), selected) << " " << std::setprecision(9) << robots.agent(selected).delay() << "\n";
        } else if (op == "robots_url") {
            std::string url;
            std::cin >> url;
            std::string out = Rep::Robots::robotsUrl(unhex(url));
            for (unsigned char c : out) std::cout << std::hex << std::setw(2) << std::setfill('0') << int(c);
            std::cout << std::dec << " .\n";
        }
    }
}
'''

donor = pathlib.Path(sys.argv[1]).resolve()
existing = json.loads(pathlib.Path(sys.argv[2]).read_text(encoding="utf-8"))
out = pathlib.Path(sys.argv[3])
git = lambda d, *a: subprocess.check_output(["git", "-C", str(d), *a], text=True).strip()
commit = git(donor, "rev-parse", "HEAD"); assert commit == "e92f22e0b6153772bb66cd41cde06a5a7ec04d66"
rep = donor / "reppy/rep-cpp"; url = rep / "deps/url-cpp"
assert git(rep, "rev-parse", "HEAD") == "9c1278b754a7284304ee263f86adadeb0297b02f"
assert git(url, "rev-parse", "HEAD") == "f9f53c7cadfbd26ab32fee1e86fa88393a1e7ddc"
assert not git(rep, "status", "--porcelain") and not git(url, "status", "--porcelain")
sources = ["src/agent.cpp", "src/directive.cpp", "src/robots.cpp"]
url_sources = ["src/url.cpp", "src/utf8.cpp", "src/punycode.cpp", "src/psl.cpp"]
work = pathlib.Path(tempfile.mkdtemp())
(work / "harness.cpp").write_text(HARNESS)
exe = work / "reppy-oracle"
compiler = subprocess.check_output(["g++", "--version"], text=True).splitlines()[0]
# url-cpp relies on <cstdint> arriving transitively, which modern libstdc++ no longer does;
# forcing the standard header on the command line leaves every donor byte unmodified.
FLAGS = ["-std=c++14", "-O0", "-include", "cstdint"]
subprocess.check_call(["g++", *FLAGS, f"-I{rep/'include'}", f"-I{url/'include'}", str(work / "harness.cpp"),
                       *[str(rep / s) for s in sources], *[str(url / s) for s in url_sources], "-o", str(exe)])
hexed = lambda s: s.encode("utf-8").hex() or "00"[:0]
lines = []
for c in existing["cases"]:
    lines.append("allowed " + " ".join(c[k].encode().hex() for k in ["robots", "url", "agent"]))
urls = ["https://shop.example/products/cup?sku=1#reviews", "http://shop.example:8080/a/b", "https://SHOP.Example/A", "https://user:pw@shop.example/x",
        "https://shop.example", "https://shop.example/", "https://shop.example/robots.txt", "https://shop.example/a?b=c&d=e", "http://shop.example:80/x",
        "https://shop.example:443/x", "https://例え.テスト/商品", "https://shop.example/%7Euser/", "https://shop.example/path;param?q#f", "https://shop.example//double"]
lines += ["robots_url " + u.encode().hex() for u in urls]
result = subprocess.run([str(exe)], input="\n".join(lines) + "\n", capture_output=True, text=True, check=True).stdout.splitlines()
assert len(result) == len(lines)
agree = 0; disagreements = []
for c, line in zip(existing["cases"], result):
    allowed, delay = line.split(); delay = None if float(delay) < 0 else float(delay)
    if (allowed == "1") == c["allowed"] and delay == c["crawl_delay_seconds"]:
        agree += 1
    else:
        disagreements.append({"case": c, "gpp": [allowed, delay]})
robots_urls = []
for u, line in zip(urls, result[len(existing["cases"]):]):
    robots_urls.append({"url": u, "robots_url": bytes.fromhex(line.split()[0]).decode("utf-8")})
generator = pathlib.Path(__file__).read_bytes()
evidence = lambda d, c, p: {"path": p, "commit_sha": c, "blob_hash": git(d, "rev-parse", f"{c}:{p}"), "sha256": hashlib.sha256(subprocess.check_output(["git", "-C", str(d), "show", f"{c}:{p}"])).hexdigest()}
fixture = {"donor_id": "seomoz--reppy", "commit_sha": commit, "license": "MIT", "oracle": "COMPILED_UNMODIFIED_DONOR_CPP_GPP",
           "compiler": compiler, "compiler_flags": FLAGS, "rep_cpp_commit": git(rep, "rev-parse", "HEAD"), "url_cpp_commit": git(url, "rev-parse", "HEAD"),
           "source_evidence": [evidence(rep, git(rep, "rev-parse", "HEAD"), s) for s in sources + ["include/robots.h", "include/agent.h", "include/directive.h", "LICENSE"]]
                              + [evidence(url, git(url, "rev-parse", "HEAD"), s) for s in url_sources + ["include/url.h", "LICENSE"]],
           "reproduction_of_msvc_fixture": {"fixture_cases": len(existing["cases"]), "gpp_agreeing": agree, "disagreements": disagreements},
           "robots_url_cases": robots_urls,
           "generator_sha256": hashlib.sha256(generator).hexdigest(), "generator_source": generator.decode("utf-8")}
out.write_text(json.dumps(fixture, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
print("allowed cases agreeing:", agree, "/", len(existing["cases"]))
for r in robots_urls: print(r)
